    "text": "【世界设定】\n时代：架空·大景王朝（穿书）\n题材：穿书宅斗\n简介：你，林晚照，一个熬夜追小说的现代社畜，在吐槽完《侯门千金》里炮灰女配林晚娘活不过三十章的愚蠢操作后，一觉醒来发现自己穿成了她。原著里，林晚娘是侯府庶女，被嫡姐利用、被继母算计、被未婚夫退婚、最终被一杯毒酒送走。但现在的你有个别人没有的优势——你知道接下来三十章里每个人的每步棋。侯府的茶里下的是什么毒，你知道；嫡姐的嫁妆箱里藏着什么，你知道；连那个看似深情的未婚夫，会在哪一章翻脸，你都一清二楚。现在的问题是：你要怎么利用这份'剧透'，活过三十章？\n规则：\n  1. 你记得原著剧情，但剧情可能因你的介入而改变——蝴蝶效应真实存在\n  2. 原身的记忆只有零散片段，重要剧情节点靠自己回忆\n  3. 古代礼教森严，庶女行事处处受限，但'穿越者优势'不只有剧透\n  4. 不能直接说出'这是小说世界'——没人信，还会被当失心疯\n  5. 侯府每个人都有自己的秘密，而你的秘密是最大的那个\n氛围：雕梁画栋的侯府宅院，朱门酒肉臭路有冻死骨的世道，现代灵魂在古宅里的格格不入\n\n【主角身份】\n姓名：林晚照\n性别：女\n年龄：15\n背景：大景靖安侯府庶女。原身怯懦愚钝，是侯府最不起眼的透明人。穿越前的你是个擅长人情世故的互联网运营，看透了各种套路。\n\n【重要人物】\n- 林晚歌（嫡姐）：温柔大方，实则工于心计；与主角：原著中的'白莲花'，所有恶事的幕后推手\n- 沈砚（未婚夫，定北侯世子）：温润如玉，风流多情；与主角：原著中第三章与你退婚，第五章迎娶你嫡姐\n- 周妈妈（继母心腹）：势力刻薄，欺软怕硬；与主角：原著中负责给你下毒的人\n- 顾衍之（侯府门客）：落拓不羁，智谋深沉；与主角：原著中并未登场的人物——这让你感到不安\n\n【时间线】\n起始：1178年4月2日\n备注：原著第三章——退婚风波前七日。你还有七天时间准备\n\n【选项风格】现代思维vs古代规则的选择题——用知识碾压，还是藏拙保命",
