    "text": "【世界设定】\n时代：架空·大梁王朝\n题材：系统穿越\n简介：一觉醒来，你——苏岁安，一个平平无奇的现代电商运营——发现自己躺在了大梁王朝一间破旧茅屋里，身边还躺着两具饿死的尸体。更要命的是，你脑子里响起了那个熟悉的'叮'：'【咸鱼商城系统已激活】宿主绑定成功，初始积分 100。'系统的规则很简单：你可以在商城里兑换任何东西——一袋大米要 10 积分，一盒青霉素要 500 积分，一件避弹衣要 3000 积分。积分从哪里来？'宿主可以通过完成历史事件节点、改变历史走向、满足'客户'心愿获得积分。'你低头看了看手中的《大梁民生志》，又看了看眼前饿殍遍野的世界——这个王朝，正在闹百年不遇的大饥荒。而离你最近的城镇里，那位即将在三个月后造反的县尉，此刻正在招工修堤。\n规则：\n  1. 积分可兑换商城物资，但越出格的商品越贵——青霉素、火器这类'黑科技'有额外溢价\n  2. 改变历史事件可获得积分，但改变幅度越大，未知风险越大\n  3. 商城购物记录会消耗'能量'，系统每天只允许 3 次兑换\n  4. 你对外出售的每件'神物'都必须编一个说得过去的来历\n  5. 系统不会替你战斗、不会替你说话，它只负责卖货\n氛围：饥荒大地上的枯骨与炊烟，商城里五光十色的现代货架，是这个时代唯一的暖色\n\n【主角身份】\n姓名：苏岁安\n性别：女\n年龄：20\n背景：穿越前是电商平台运营，精通选品、定价、营销话术。穿越后成为大梁王朝无籍流民，栖身破庙。\n\n【重要人物】\n- 秦望舒（县尉，未来的造反者）：深沉果决，爱民如子；与主角：三个月后他将揭竿而起——你是选择阻止他，还是帮他？\n- 老周头（破庙邻居）：憨厚朴实，见多识广；与主角：第一个接受你'神物'的人，帮你把名声传了出去\n- 陆知微（刺史府长史）：精明干练，疑心深重；与主角：正在暗中调查'县城神药'的来历——他怀疑有妖人作祟\n- 系统（咸鱼商城系统）：毒舌，奸商，偶尔良心发现；与主角：你的金手指，也是你最大的秘密\n\n【时间线】\n起始：1140年2月11日\n备注：大梁崇元三年春，饥荒第二年。离县尉造反还有九十二天\n\n【选项风格】资源管理型选项：每花一分积分都要想清楚值不值",
