    "text": "【世界设定】\n时代：现代·都市\n题材：都市\n简介：前世的你是仙医门的关门弟子，医武双绝，却遭同门背叛，陨落于天劫之下。再睁眼，你成了都市里一个刚被裁员、身无分文、身患绝症的青年程序员林小满。前世仙术犹在，这一世你左手救人，右手算账：用针灸治疑难杂症，用医术换资本入场券，在钢筋水泥的丛林里重登巅峰——顺便查清一个谜：前世那场背叛，幕后黑手似乎也转世到了这座城市。\n规则：\n  1. 仙医门医术不能公开暴露，否则引来追杀\n  2. 每次动用仙术疗伤都会消耗寿元，须以丹药补回\n  3. 都市规则：医术换钱，钱换势力，势力换情报\n  4. 同门转世者也可能在这座城，敌友未明\n  5. 医院、资本、地下势力——三张牌要打得恰到好处\n氛围：写字楼的玻璃幕墙映着晚霞，城中村的出租屋里亮着一盏孤灯，药香混着键盘声\n\n【主角身份】\n姓名：林小满\n性别：男\n年龄：25\n背景：被裁员的前端程序员，确诊肺癌晚期，重生后体内残留仙医门神诀，靠针灸与丹药续命并改变命运\n\n【重要人物】\n- 合租室友·大壮（房产中介）：憨厚讲义气；与主角：唯一的现实朋友，处境也艰难\n- 前女友·苏晚（三甲医院医生）：理性冷静，医者仁心；与主角：当年嫌你穷分手，如今是行业资源\n- 资本大佬·韩爷（地下赌场与医馆老板）：笑面虎，手段狠辣；与主角：你展露医术后的合作与麻烦\n- 神秘少女·雪儿（来历不明的病人）：沉默寡言，身怀异术；与主角：你救过的病人，疑与前世的你有关\n\n【时间线】\n起始：2026年9月1日\n备注：你重生的第三天，体检报告确认肺癌晚期，房东来催租，而苏晚发来一条信息：她的父亲得了怪病，想求医\n\n【选项风格】选项要带重生者的冷静算计（如：先续命/先赚钱/先治病/先布局）",
