    "text": "【世界设定】\n时代：清·雍正年间\n题材：宫斗重生\n简介：你是雍正后宫的娴妃沈云璃，三年前因卷入储位之争被构陷打入冷宫。今夜你从噩梦中惊醒，却发现自己回到了刚入冷宫的第一天——你带着这三年的记忆重生了。你清楚记得每个人说的每句话、每个陷阱的位置，甚至记得前世自缢而死的贴身宫女春杏。这一次，你要夺回荣宠，揪出构陷你的真凶，护住那个本该死在你怀里的孩子。\n规则：\n  1. 宫规森严，言行必须合身份，出格即授人以柄\n  2. 后宫无小事，一句话、一件衣饰皆可成为攻讦的刀\n  3. 妃嫔不得直接结交朝臣，只能借宫人、太医、太监传话\n  4. 重生记忆是唯一底牌，绝不可让任何人察觉你有未卜先知之能\n  5. 皇帝多疑，恩宠越是炽烈，越是万劫不复\n氛围：朱墙碧瓦下的肃杀，表面繁花似锦，实则每一片花瓣下都藏着刀\n\n【主角身份】\n姓名：沈云璃\n性别：女\n年龄：18\n背景：将门之女，父沈镇官拜副都统。因父功入宫封娴妃，性情温婉藏锋芒。三年前被构陷与禁卫军总管私通，皇帝震怒，褫夺封号打入冷宫。\n\n【重要人物】\n- 皇后乌雅氏（中宫皇后）：端庄慈和，绵里藏针；与主角：表面善待你，实为储位之争的操盘手\n- 年贵妃（宠冠六宫）：明艳张扬，笑里藏刀；与主角：当年构陷你私通的主谋，与皇后暗中角力\n- 李德海（御前总管太监）：见风使舵，八面玲珑；与主角：皇帝身边最信任的人，谁给的好处多就为谁说话\n- 春杏（贴身宫女）：忠厚单纯，胆小怕事；与主角：前世为你挡下毒药自缢身亡，这一世你最想护住的人\n\n【时间线】\n起始：1725年3月1日\n备注：雍正三年三月初一，你重生的日子。前世的牢狱之灾即将在三十日后上演\n\n【选项风格】宫斗选项必须权衡利弊——一步错，步步错，人人都有两副面孔",
