    "text": "【世界设定】\n时代：架空·大昭王朝\n题材：后宫权谋\n简介：大昭新帝昭明帝登基三月，后宫空悬。各地秀女齐聚储秀宫，而你是其中最不起眼的一个——江南织造之女顾惊鸿，无显赫家世，却因一纸匿名'昭华令'被钦点入宫。传闻昭华令出，必出皇后：先帝的皇后、太宗的皇后，皆出自昭华令点选。可你清楚，这世上没有白来的恩宠。先帝晚年三度易后，皆因昭华令而起。究竟是谁在幕后写下你的名字？这道令，是命运垂青，还是有人布下的杀局？\n规则：\n  1. 昭华令只有一纸，持令人即天子钦定的后位人选，但也因此成为众矢之的\n  2. 选秀三选三看：初选看容貌家世，复试考才艺心性，终选由皇帝亲择\n  3. 新帝勤政，明令后宫不得干政，违者贬为庶人\n  4. 后宫按份例供给，无品级妃嫔不得逾矩，礼部与内廷监监督一切\n  5. 昭华令可转授——若持令人自愿让出，后位之争便重新开始\n氛围：江南烟雨与大内琉璃的碰撞，暗香浮动月黄昏，人人脸上都带着一层面纱\n\n【主角身份】\n姓名：顾惊鸿\n性别：女\n年龄：17\n背景：江南织造府养女，生父生母不详。自幼长在织造府后园，通音律、善丹青，性子沉静，却有一双能看透人心的眼睛。\n\n【重要人物】\n- 萧衍（大昭昭明帝）：年轻冷峻，深不可测；与主角：你的钦点之人，从不表露喜怒，却总在你意料之外的地方出现\n- 沈贵妃（先帝旧人，贵妃）：雍容圆滑，滴水不漏；与主角：后宫实际掌权者，对昭华令持令人怀有复杂态度\n- 钦天监监正（卜算昭华令之人）：仙风道骨，语焉不详；与主角：曾对你说：'令出无声，祸福自渡'——你至今不明白这句话\n- 顾临渊（织造府少东家）：温文尔雅，藏锋于鞘；与主角：名义上的义兄，实际暗中查探你的身世多年\n\n【时间线】\n起始：1172年8月15日\n备注：昭明三年仲秋，你入储秀宫第一日。七日后为初选，十五日后为终选\n\n【选项风格】每一步选择都可能改变后位归属，谨慎为上，但也要有赌徒的胆量",
    "sourceType": "official",
    "pinned": false,
    "order": 13
