    "text": "【世界设定】\n时代：公元2387年·星际殖民\n题材：科幻\n简介：「晨曦号」殖民星舰载着五千名殖民者飞向新家园，航程三十年，而你只是个维修员——舰上最不起眼的岗位。直到一次例行检修，你在货舱底层发现了一个不该存在的舱门：门后是一间完整的中世纪城堡，城堡的钟楼里，住着一个自称「守钟人」的机器人。它说：这艘船已经飞了三十个世纪，你的飞船，只是某个更大的秘密的一部分。\n规则：\n  1. 星舰有严格的维修规程，越权检修会被记过\n  2. 舰上 AI 中枢「晨曦」监控一切，但货舱底层是盲区\n  3. 能源有限，殖民地的命运取决于每一次正确的选择\n  4. 沉睡的殖民者舱位有编号，有些编号查无此人\n  5. 守钟人的话半真半假，但它从未撒谎\n氛围：金属走廊的灯管嗡鸣，货舱里堆着冷冻舱的幽蓝色光，钟楼的钟声从不该存在的地方传来\n\n【主角身份】\n姓名：阿彻\n性别：男\n年龄：27\n背景：晨曦号维修员，编号 M-447，第五代殖民者后代，从没离开过飞船，天生好奇，修过舰上所有的东西\n\n【重要人物】\n- 舰长·伊莱（晨曦号舰长）：沉稳威严，深藏秘密；与主角：他似乎知道那个舱门的存在\n- AI·晨曦（舰载智能中枢）：冷静理性，拥有人格；与主角：你的顶头上司，也是最大的监视者\n- 守钟人·T8（舱门后的机器人）：博学温和，像位老绅士；与主角：自称等你很久了\n- 维修主管·老鲁（维修部主管）：粗犷豪爽，护犊子；与主角：把你当亲徒弟，提醒你别碰货舱底层\n\n【时间线】\n起始：2387年2月11日\n备注：晨曦号航程第 231 年，你按规程检修货舱时，发现了那个舱门\n\n【选项风格】选项要带科幻的推演感（如：上报舰长/独自探查/查殖民者名单/解码晨曦日志）",
    "sourceType": "official",
