    "text": "【世界设定】\n时代：2050年代·义体都市\n题材：科幻\n简介：2056年，人类寿命突破150岁，代价是器官供不应求。于是出现了「器官农场」——用克隆人养殖备用器官。你叫「零号」，是农场里最新的一批克隆体，本应在一周后提供心脏。但一次意外，农场的 AI 安保系统错误地把你标记为「公民」，你带着一张不属于自己的身份证，逃进了霓虹都市的缝隙里。这座城市有一万个人长得和你一模一样——他们全是你的「兄弟」，而你知道，其中三个已经「被回收」了。\n规则：\n  1. 克隆人没有公民权，被抓住就是「回收」\n  2. 你的脸是大众脸，监控识别系统会扫到你一万次\n  3. 义体都市里，身份芯片比钱重要\n  4. 农场 AI 会追踪你，但它的权限有漏洞\n  5. 「兄弟」们有的在逃，有的在举报你，有的在帮你\n氛围：霓虹灯牌永不熄灭，雨在电子屏幕上滑出彩色条纹，街角飘着烤淀粉的味道和低频的引擎声\n\n【主角身份】\n姓名：零号\n性别：男\n年龄：19（出厂）\n背景：器官农场 7 号克隆体，本无记忆，因安保事故意外植入了一段「原始体」的记忆碎片——那段记忆里，有一个女孩，和他长得不一样\n\n【重要人物】\n- 流浪医生·老K（黑市医生）：嘴硬心软，技术高超；与主角：愿意帮你换身份芯片，但要你替他跑腿\n- 兄弟·三号（先你逃出的克隆体）：谨慎多疑，神经质；与主角：知道农场更多秘密，但也可能出卖你\n- 义警·铁兰（城市治安官）：冷厉高效，有洁癖；与主角：负责回收逃逸克隆体，她的档案里记录着每个克隆体的编号\n- 记忆里的女孩·小满（原始体的妹妹）：温柔坚韧，在找你；与主角：你在城市的地下乐队里遇到了她，她看着你的脸愣住了\n\n【时间线】\n起始：2056年4月3日\n备注：你逃出农场第 3 天，身份芯片的合法有效期还剩 72 小时，老K 的报价是三万信用点\n\n【选项风格】选项要带生存压迫感（如：换芯片/躲监控/找三号结盟/查原始体记忆）",
