    "text": "【世界设定】\n时代：公元前221年·秦朝\n题材：历史\n简介：秦王扫六合，虎视何雄哉。你叫李默，是咸阳郡一名小小的书吏，专管户籍与粮册。帝国机器轰鸣向前，律法如铁，每一条都在压着人往下走：连坐、徭役、焚书、长城。你手里那本户籍册，记着三万七千户人家的生老病死——而朝廷新下的诏令，要你从册子里找出「黔首家富者」充实咸阳。你知道，名单交上去，就会有人被连根拔起。可你不交，明天被挂在城门口的就是你。\n规则：\n  1. 秦律严苛：连坐之罪，知情不报者同罪\n  2. 户籍册即权力，动一处数字可救人亦可杀人\n  3. 焚书令下，私藏诗书者罚城旦舂\n  4. 咸阳的鹰犬（廷尉府探子）无孔不入\n  5. 一统天下后的帝国，容不下「多余」的人\n氛围：咸阳城的夯土城墙下，车马辚辚，衙署里的竹简堆成小山，烛火照着一地阴影\n\n【主角身份】\n姓名：李默\n性别：男\n年龄：27\n背景：咸阳郡书吏，管户籍粮册五年，出身贫寒，靠一手好字被举荐入衙，深知民间疾苦，也深知秦律的份量\n\n【重要人物】\n- 上司·赵御史（咸阳郡御史）：冷硬刻板，执法如山；与主角：你的顶头上司，铁面无私\n- 同僚·王茂（衙署书吏）：油滑圆熟，见风使舵；与主角：你的同僚，擅长自保\n- 村妇·刘媪（渭南农户）：坚韧泼辣，护犊如命；与主角：她的儿子被列为「家富者」，即将被征入咸阳\n- 神秘的酒客·青衫客（咸阳酒肆常客）：洒脱不羁，见识广博；与主角：似乎认得太多的字，太多的事\n\n【时间线】\n起始：2026年1月1日\n备注：秦灭齐统一六国，咸阳诏令频下，你手中的户籍册是第三批「家富者」名单的底册\n\n【选项风格】选项要带秦律的冰冷与现实（如：如实上报/篡改数字/放风通风/借酒醉拖延）",
