    "text": "【世界设定】\n时代：万历年间·大明\n题材：历史\n简介：大明万历年间，锦衣卫如影随形。你叫陆夜，是北镇抚司一名新晋校尉，刚满二十，办的第一桩案子，是查抄吏部侍郎家。抄家时，你在侍郎书房的暗格里发现一封没有署名的密信，信上只有八个字：「龙椅之下，绣春刀凉。」你本想按规程上交，可当晚，你的上官、那个办案多年的老档头，死在了自己屋里，手里攥着同样的八个字。你突然明白：这桩案子，背后是能让你万劫不复的棋局。\n规则：\n  1. 锦衣卫规程：密信、密档、密诏，层层设限\n  2. 北镇抚司的诏狱，进去的人没有「出来」的\n  3. 万历皇帝久不上朝，党争如火，东厂与锦衣卫明争暗斗\n  4. 绣春刀出鞘前，先想清楚刀口朝向谁\n  5. 知道的越多，死得越快——但死得明白的人，才有价值\n氛围：北镇抚司的阴冷廊道里，灯笼明明灭灭，诏狱深处传来铁链拖地的声响\n\n【主角身份】\n姓名：陆夜\n性别：男\n年龄：20\n背景：北镇抚司新晋校尉，世袭的锦衣卫家庭出身，父亲是老千户，教他刀法也教他「少看少问」。刚办完第一桩大案，就卷进密信之局\n\n【重要人物】\n- 父亲·陆千户（锦衣卫千户）：老练深沉，惜字如金；与主角：他让你「装瞎」，但你知道他藏着旧事\n- 档头·赵九（北镇抚司档头）：阴鸷寡言，掌管密档；与主角：你的直属上司，案发后第一个找你谈话\n- 东厂督公·冯保（东厂提督太监）：城府极深，笑里藏刀；与主角：他也在查这八个字，来历不善\n- 密信人·白衣客（神秘送信人）：神出鬼没，武功高强；与主角：他在你深夜回衙的路上，等了你两晚\n\n【时间线】\n起始：1583年4月2日\n备注：老档头死后第三天，赵九把查抄侍郎家的案卷重新压在你桌上，上面多了八个字批注：继续查，往宫里查\n\n【选项风格】选项要带锦衣卫的杀伐与隐忍（如：密查线索/上交密信/试探父亲/见白衣客）",
