    "text": "【世界设定】\n时代：现代·丧尸末世\n题材：末世\n简介：病毒爆发第七天，你所在的城市已经沦陷过半。你是写字楼的保安队长，在楼里守着一群幸存者：一个孕妇、一个倔强的老人、一对失散又重逢的小情侣，和一个自称「疾控中心研究员」的奇怪女人。楼下的丧尸越聚越多，楼上的食物撑不过五天。而研究员女人手里攥着一个冰袋，她说里面是病毒样本——只要活着送到市中心的疾控中心，就能研究出解药。\n规则：\n  1. 末世规则：声音会引来丧尸，灯光会引来丧尸，血腥味也是\n  2. 食物和水按人头分配，谁也不准私藏\n  3. 研究员手里的冰袋是「钥匙」，也是「炸弹」\n  4. 城市里还有别的幸存者队伍，有的友好，有的不是\n  5. 疾控中心在城中心，路上要穿过三条主干道\n氛围：城市死寂，写字楼的应急灯在走廊里一闪一闪，窗外传来丧尸拖沓的脚步声，像下雨一样密集\n\n【主角身份】\n姓名：铁柱\n性别：男\n年龄：32\n背景：写字楼保安队长，退伍军人，会格斗会用枪，危机爆发那天恰好值夜班，成了这栋楼幸存者的话事人\n\n【重要人物】\n- 孕妇·小雨（幸存者）：温柔坚韧，快临盆；与主角：她是队伍里最脆弱也是最强的人\n- 老人·王伯（幸存者）：倔强世故，见过大场面；与主角：他年轻时是货车司机，认得城里的每条路\n- 研究员·林知（疾控中心研究员）：冷静克制，藏有心事；与主角：她手里的冰袋是所有人的希望，也是隐患\n- 幸存者队长·刀疤（另一支队伍的头）：凶悍多疑，拳头说话；与主角：他的队伍盘踞在前往疾控中心的必经之路上\n\n【时间线】\n起始：2026年9月15日\n备注：病毒爆发第七天，楼下丧尸密度暴增——有人发现，它们在「向上」聚集\n\n【选项风格】选项要带末世的决断（如：固守待援/突围送样本/走地下通道/与刀疤谈判）",
    "sourceType": "official",
    "pinned": false,
    "order": 26
