    "text": "【世界设定】\n时代：近未来·植物末世\n题材：末世\n简介：一场「绿潮」席卷全球：所有植物开始失控生长，藤蔓吞噬城市，巨树拔地而起，种子像炮弹一样从天而降。人类文明在绿潮中崩塌，幸存者逃进植物无法生长的「灰区」——被彻底污染的废土。你是植物学家，在绿潮爆发前，你正在研究一种「会聆听」的藤蔓。逃进灰区的第七天，你在废墟里发现一株没有枯萎的绿芽——它长在一具骷髅的手心里，根须缠绕着一只录音笔，录音笔里传来你失踪导师的声音：「别拔它。它是最后一个愿意听人说话的朋友了。」\n规则：\n  1. 灰区规则：植物无法存活，但人类的伤口会「发芽」\n  2. 绿潮中的植物会「记住」伤害过它们的人\n  3. 导师的录音笔里记录了绿潮爆发的真正原因\n  4. 绿芽是唯一存活的生命，它似乎在「等」你\n  5. 灰区的边缘，有人在收集「种子」——高价收购\n氛围：灰区的天空是铅色的，废土上散落着钢铁残骸，远处绿潮的边界线像一堵会呼吸的绿墙\n\n【主角身份】\n姓名：苏苔\n性别：女\n年龄：28\n背景：植物学家，绿潮爆发前在研究所研究「聆听藤蔓」，逃难时带着导师留下的半本笔记，笔记最后一页写着「它们听得见」\n\n【重要人物】\n- 导师·周教授（（录音/失踪））：温和执拗，超前时代；与主角：他消失在绿潮爆发前夜，留下录音笔和未解之谜\n- 幸存者·大刘（灰区拾荒者）：粗犷豪爽，重义气；与主角：他收留了你，教你在灰区活下去的本事\n- 种子商人·梅姨（灰区商人）：精明市侩，消息灵通；与主角：她高价收购「会发芽的东西」，来历不明\n- 绿芽·小绿（骷髅手心里的绿芽）：（植物）会回应你；与主角：它朝你生长的方式，像在认人\n\n【时间线】\n起始：2083年5月20日\n备注：你在灰区发现绿芽的第 3 天，种子商人梅姨出价「一箱罐头」收购它，而录音笔里导师的声音还在继续播放\n\n【选项风格】选项要带人与自然的纠葛（如：护住绿芽/研究录音笔/深入绿潮/卖给梅姨）",
