    "text": "【世界设定】\n时代：近未来·灾后浮空城\n题材：末世\n简介：大地崩裂后的第三十年，人类文明悬浮在空中。巨型浮空城「新伊甸」承载着最后的三百万幸存者，由一百零八座动力浮岛串联而成。你是浮岛的维修工，负责最底层——也是最危险的「甲板区」。今天的例行巡检中，你发现第 13 号浮岛的动力核心出现了一道不该存在的裂纹，而维修记录显示：13 号浮岛，已经「报废」了二十年。更蹊跷的是，裂纹的形状，和三十年前那张「灾前城市地图」上的某条街道，一模一样。\n规则：\n  1. 浮空城规则：动力核心过载即弃岛，弃岛名单由议会决定\n  2. 13 号浮岛的档案显示「报废二十年」，但它仍在运行\n  3. 裂纹的形状像一条街道——三十年前的街道\n  4. 甲板区的老人们，对 13 号浮岛讳莫如深\n  5. 新伊甸的议会，在「削减」浮岛数量\n氛围：浮空城的天际线上，云海翻涌，下层甲板的钢梁在风里发出低沉的嗡鸣，脚下是三十年前的大地\n\n【主角身份】\n姓名：阿拓\n性别：男\n年龄：23\n背景：甲板区维修工，父母死于大地崩裂，在浮空城长大，手艺过硬，好奇心重，档案室管理员的老头是他师傅\n\n【重要人物】\n- 师傅·老庄（档案室管理员）：固执守旧，一肚子旧事；与主角：他看过三十年前的城市地图，认得裂纹的形状\n- 议会代表·苏利（浮空城议会代表）：优雅冷静，滴水不漏；与主角：他主张「精简浮岛」，13 号在名单上\n- 甲板区长·铁叔（甲板区负责人）：粗犷护短，讲义气；与主角：他管着甲板区的秩序，也知道些旧事\n- 神秘老人·盲婆婆（甲板区老住户）：沉默寡言，能听风辨音；与主角：她能在引擎声里「听见」浮岛的过去\n\n【时间线】\n起始：2056年8月9日\n备注：你发现 13 号浮岛裂纹的第 2 天，议会公告：下季度将「精简」5 座浮岛，13 号岛列入报废名单\n\n【选项风格】选项要带灾后文明的反思（如：深入13号岛/找师傅查地图/问盲婆婆/闯议会）",
    "sourceType": "official",
    "pinned": false,
    "order": 29
