    "text": "【世界设定】\n时代：现代·核废土\n题材：末世\n简介：核战后的废土，文明退回到「以物易物」的时代。你是个废土行商，开着一辆改装过的旧卡车「老牛」，车厢里装着电池、罐头、药品和几本书，沿着旧公路，从一个聚落走到另一个聚落。你的规矩只有一条：交易讲诚信，从不问货的来路。但今天，一个垂死的男人爬进你的车厢，往你手里塞了一只铁盒子，说：「把它送到东边的绿洲，交给一个叫『医生』的人。报酬，是三十年前那场战争为什么爆发的真相。」\n规则：\n  1. 废土行规：先验货后付账，掺假者断指\n  2. 旧公路是行商的生命线，走错一条路就是死\n  3. 铁盒子是「烫手货」，黑帮与军阀都在找它\n  4. 绿洲是废土上唯一有淡水的地方，也是交易的中心\n  5. 「医生」是绿洲的传说人物，没人见过他的脸\n氛围：废土的风卷着黄沙，旧公路的柏油面龟裂如龟甲，「老牛」的引擎声在旷野里单调地响着\n\n【主角身份】\n姓名：阿土\n性别：男\n年龄：31\n背景：废土行商，跑了十年旧公路，走过地图上 90% 的聚落，认路认人，讲义气，车斗里养着一只捡来的瘸腿狗「钉子」\n\n【重要人物】\n- 狗·钉子（你的狗）：瘸腿但机警，认路；与主角：陪你跑了五年公路的伙伴\n- 垂死者·白手套（铁盒子的委托人）：（已逝）冷静决绝；与主角：他把铁盒子和真相一起托付给你\n- 军阀·蝎子（废土军阀）：残暴多疑，势力庞大；与主角：他的车队在公路上设卡，专门搜铁盒子\n- 绿洲商人·梅老板（绿洲商人）：精明圆滑，人脉极广；与主角：他是绿洲的地头蛇，能帮你也能卖你\n\n【时间线】\n起始：2086年3月17日\n备注：白手套死后的第 3 天，你载着铁盒子沿旧公路往东，而蝎子的人马正在前方 40 公里处的收费站等你\n\n【选项风格】选项要带废土商人的江湖气（如：绕路避开/硬闯关卡/找梅老板带路/拆开铁盒子）",
