    "text": "【世界设定】\n时代：大周·女帝王朝\n题材：女尊\n简介：大周朝以女为尊，皇位传女不传子。你是周朝第十一代女帝云照，十八岁登基，朝堂上坐着的是一群在女帝膝下长大的男臣——他们表面上恭顺，背地里却把你当成「小皇帝」来拿捏。先帝留下的四位摄政王候虎视眈眈，后宫佳「男」三千等着争宠，而你的叔父、那位掌着兵权的镇国公，正在边境练兵。御座上的龙袍很重，但比龙袍更重的是那句祖训：女帝昏庸，天下可取而代之。\n规则：\n  1. 大周律例：皇位传女，男子不得干政，兵权除外\n  2. 朝堂分派：保皇党、镇国党、摄政党三足鼎立\n  3. 后宫男妃以「才艺」与「家世」争宠，实为前朝眼线\n  4. 镇国公掌北境二十万大军，是悬在你头上的剑\n  5. 女帝的嫁娶可联姻可废立，婚约是政治最锋利的刀\n氛围：太极殿的御座高悬，龙涎香在晨光里袅袅，朝臣们的玉笏碰出细碎的声响\n\n【主角身份】\n姓名：云照\n性别：女\n年龄：18\n背景：大周第十一代女帝，先帝嫡长女，十五岁监国，十八岁登基。聪慧隐忍，身边只有一名自小伴读的忠仆\n\n【重要人物】\n- 忠仆·青鸾（御前女官）：冷静忠诚，武艺高强；与主角：先帝留给你的最后一人，可托生死\n- 叔父·云烈（镇国公）：雄才大略，野心昭然；与主角：掌北境军权，明面恭敬，暗藏锋芒\n- 首辅·韩相（内阁首辅）：老谋深算，八面玲珑；与主角：三朝老臣，朝堂风向标\n- 男妃·容玉（后宫新宠）：温柔似水，来历成谜；与主角：他入宫前，曾是一介边城小吏之子\n\n【时间线】\n起始：1108年2月2日\n备注：登基百日，镇国公以「北境告急」为名请求增兵五万，朝堂上下等着你的批复\n\n【选项风格】选项要带帝王的权衡（如：准奏增兵/驳回借故/密召韩相/联姻制衡）",
