    "text": "【世界设定】\n时代：架空·烽火边关\n题材：女尊\n简介：大燕朝以女为尊，边关二十三城，守将皆是女帅。你叫秦照雪，秦家军第七代女帅，十二岁上马，十六岁挂帅，打了九年仗，从无败绩。可这次，你面对的是一场没有敌人的战争：粮道断了、军心散了、朝中送来一道「换帅」的圣旨，接替你的是你的亲妹妹秦照月。你比谁都清楚：敌军就在三十里外扎营，而朝中那位递奏本的文官，姓秦——你的堂叔。\n规则：\n  1. 军令如山：帅印在手，违者斩；帅印易主，旧帅缴械\n  2. 边关二十三城互为犄角，一城失则全线危\n  3. 粮道被断半月，军中已现逃兵\n  4. 接印的新帅是你亲妹，她此行的目的却成谜\n  5. 敌军在三十里外扎营，他们等的，是你们的帅印交接\n氛围：边关的朔风卷着黄沙，城头的旌旗猎猎作响，军营里的火把连成一线，远处敌营的灯火忽明忽暗\n\n【主角身份】\n姓名：秦照雪\n性别：女\n年龄：25\n背景：秦家军第七代女帅，九年来守边关二十三城未失一城，军中威望极高，视士兵如手足\n\n【重要人物】\n- 副将·铁娘子（秦家军副将）：忠勇刚烈，快人快语；与主角：跟你打了八年仗的生死之交\n- 妹妹·秦照月（新任女帅）：冷峻疏离，深不可测；与主角：她带着圣旨来接印，态度却不像来夺权的\n- 军师·柳先生（秦家军军师）：老谋深算，足智多谋；与主角：他察觉出粮道被断与朝中有关\n- 敌帅·拓跋燕（北境敌帅）：骁勇善战，诡计多端；与主角：与你在战场交手三次，三次平手\n\n【时间线】\n起始：1523年10月14日\n备注：换帅圣旨到达的当天深夜，探马来报：敌帅拓跋燕的大军，突然移营三十里，逼近边境\n\n【选项风格】选项要带帅者的果决（如：拒交接印/合兵出击/先查粮道/交印试探）",
