    "text": "【世界设定】\n时代：暮光之都·赫利翁学院\n题材：奇幻\n简介：赫利翁魔法学院，大陆最古老的魔法学府，只招收天赋者。你叫凯特，是个连学徒资格都没有的平民少年，却在入学测试中唤醒了沉睡千年的「元素之核」——学院长当场宣布录取你，并亲自为你戴上一枚无法摘下的魔法手环。全院轰动，有人称你「命运之子」，有人私下叫你「灾星」。而你只知道：手环在午夜会发热，它会带你做同一个梦——梦里有一座沉入海底的学院，和一句等你回答的话。\n规则：\n  1. 赫利翁的规矩：元素分系、禁咒有令、血统不碰\n  2. 手环是命运之环，戴上即绑定，摘不下的方法只有三种\n  3. 午夜的热梦是「海渊之院」的召唤，只有你一人能梦到\n  4. 学院里的每一扇门，都有它「该开」的时机\n  5. 传说赫利翁建院之时，有一半的学院沉入了海底\n氛围：赫利翁的高塔在暮光中泛着蓝光，走廊里漂浮着会发光的魔法书，食堂的汤锅会自己唱歌\n\n【主角身份】\n姓名：凯特\n性别：男\n年龄：15\n背景：渔村长大的平民少年，从未接触过魔法，因在入学测试中意外唤醒元素之核而被破格录取，戴上了命运手环\n\n【重要人物】\n- 学院长·梅林（赫利翁学院长）：慈祥深邃，知晓一切；与主角：他亲自录取你，也第一个回避你的问题\n- 室友·阿尔文（贵族魔法生）：傲慢好胜，心直口快；与主角：看不起你的出身，却总在暗处帮你\n- 图书管理员·安格斯（禁书区管理员）：古怪健忘，知识渊博；与主角：他认得海渊之院的图案\n- 神秘黑猫·墨（学院里的黑猫）：高傲机敏，能通人语；与主角：它总在你手环发热时出现，像在等什么\n\n【时间线】\n起始：776年9月1日\n备注：入学第一周的午夜，手环第一次发热，你梦见了沉入海底的学院——它的大门，正缓缓打开\n\n【选项风格】选项要带学院生活的成长与魔法世界的奇妙（如：钻研元素课/夜探禁书区/追问学院长/追黑猫）",
