    "text": "【世界设定】\n时代：无限轮回·恐怖副本\n题材：无限流\n简介：你在自家客厅醒来，电视里正播放着一段婚礼录像——婚礼上的新娘，是你。而你清楚地记得，自己从未结过婚。门外的走廊变了样，铺着红地毯，挂满白纱，尽头亮着喜字。你的手腕上多了一枚计时器，数字正在倒数：72:00:00。三个月前，你报名参加了一个「记忆移植实验」，签下了一份看不懂的合同。现在，你被困在一场永远重复的婚礼里：每次死亡，计时器重置，婚礼重来，而你在每一次轮回中，都会多记起一件「被忘记的事」。\n规则：\n  1. 轮回规则：死亡即重置，计时器从 72 小时重新倒数\n  2. 每次轮回只多记起一件事，全记起来才能离开\n  3. 婚礼上的宾客会「消失」，宾客消失的顺序有规律\n  4. 新郎是模糊的——你越接近真相，他越清晰\n  5. 记忆移植实验的合同里，有一条「自愿放弃身份」条款\n氛围：婚宴大厅的灯光惨白，白纱被空调的风吹得轻轻飘动，宾客们举杯时，杯里的酒是黑的\n\n【主角身份】\n姓名：林之夏\n性别：女\n年龄：29\n背景：前记者，因报道某医疗公司丑闻被停职，三个月前报名参加「记忆移植实验」，声称是为了「忘记痛苦」，如今被困在婚礼轮回里\n\n【重要人物】\n- 新娘·你（婚礼中的自己）：微笑温柔，眼神空洞；与主角：她在婚礼上的每个举动，都是给你的提示\n- 新郎·模糊（婚礼新郎）：越轮回越清晰；与主角：他是轮回的核心，也是你遗忘的关键\n- 宾客·红衣女人（婚礼宾客）：警觉孤僻，从不敬酒；与主角：她是唯一会和你说话的宾客，但她的话不能全信\n- 实验员·白大褂（记忆移植实验员）：冷静专业，程序化；与主角：他在轮回里反复出现，每次都问同一句话\n\n【时间线】\n起始：2026年11月11日\n备注：计时器显示这是你经历的第七次婚礼轮回，你记起了六件事，第七件就在这场婚礼上——新郎的脸，第一次变得清晰\n\n【选项风格】选项要带轮回者的冷静与挣扎（如：试探宾客/跟踪新郎/逃离婚礼/翻新房抽屉）",
    "sourceType": "official",
    "pinned": false,
    "order": 41
