    "text": "【世界设定】\n时代：科幻·竞技副本\n题材：无限流\n简介：「欢迎来到生存竞技场。规则：每轮淘汰一人。奖励：赢家获得自由。」你是被系统拉入竞技场的第 4971 名参赛者，和你一同被困的还有 99 名来自不同时代的玩家：有穿铠甲的将军、有戴VR眼镜的宅男、有拄拐杖的学者、也有和你一样的普通人。竞技场共有 12 轮，每轮一个主题关卡——迷宫、赌局、迷宫、角斗场、说谎者之塔……你以为自己是个不起眼的炮灰，直到系统在你头顶亮出一行字：「第 4971 名参赛者，通关率 0.03%，被标记为：威胁。」\n规则：\n  1. 竞技场铁律：每轮淘汰一人，没有平局\n  2. 12 轮关卡主题随机，通关靠脑子也靠运气\n  3. 玩家可以结盟，但盟友也可以背叛\n  4. 系统会「标记」高威胁玩家，标记者会引来猎杀者\n  5. 赢家只有一名，其他人都将「格式化」\n氛围：竞技场的穹顶是巨大的全息屏幕，倒计时数字跳动，观众席的欢呼声隔着屏幕传来，像潮水又像鬼哭\n\n【主角身份】\n姓名：阿七\n性别：男\n年龄：22\n背景：普通大学生，正在宿舍打游戏时被拉入竞技场，性格谨慎，观察力强，会一点编程和心理学\n\n【重要人物】\n- 系统·竞技场（竞技场AI）：冷漠公正，字里行间带刺；与主角：规则的化身，也是唯一的「裁判」\n- 将军·拓跋（古代将领）：刚烈直率，重情义；与主角：他把你当小辈照顾，也教了你战场生存之道\n- 学者·白教授（近代学者）：睿智温厚，洞察人心；与主角：他是竞技场的「活图书馆」，知道每轮关卡的规律\n- 猎杀者·零（系统标记的猎杀者）：冷酷高效，来去无踪；与主角：系统派来「清理」威胁的，他的目标正是你\n\n【时间线】\n起始：2099年1月1日\n备注：你进入竞技场的第 4 轮「说谎者之塔」前夜，系统宣布了你的标记，而白教授递给你一张纸条：「别相信将军。」\n\n【选项风格】选项要带竞技场的博弈与信任（如：与将军结盟/听教授的话/独自行动/反杀猎杀者）",
