    "text": "【世界设定】\n时代：现代·梦境副本\n题材：无限流\n简介：「梦疗中心」的广告说：只要注射梦境药剂，就能在梦里疗愈创伤。你为了治疗失眠，走进这家诊所，注射后的第一夜，你梦见自己站在一座镜面迷宫的中央。迷宫由无数面镜子组成，每面镜子里都有一个「你」——快乐的你、愤怒的你、胆小的你、还有镜子里那个始终背对着你的「你」。梦疗师说：穿过迷宫，你就能治愈失眠。但你在迷宫里发现了一具尸体——尸体穿着梦疗师的白色制服，胸口插着你的名片。\n规则：\n  1. 梦境规则：迷宫里的镜子不能打破，打破会「丢失」一面镜子里的你\n  2. 梦里的时间流速是现实的 100 倍，一夜等于现实十分钟\n  3. 镜子里的「你」会说话，但每个「你」只说实话的一部分\n  4. 背对着你的那个「你」，是你遗失的恐惧\n  5. 在梦里找到的尸体，在现实里会「对应」出现\n氛围：迷宫的镜面光洁如湖，倒映出无数个自己，脚步落下时，回音在镜廊里荡来荡去，分不清来处与去处\n\n【主角身份】\n姓名：许眠\n性别：女\n年龄：25\n背景：失眠三年的心理咨询师，为了「亲测」梦境疗法走进梦疗中心，却发现自己被卷进一个无法醒来的梦境迷宫\n\n【重要人物】\n- 梦疗师·白医生（梦疗中心医师）：温和专业，滴水不漏；与主角：他为你开的第一支药剂，剂量「稍微」超了标\n- 镜中的你·笑面（快乐的自己）：开朗外向，话多；与主角：她总在引你往迷宫深处走\n- 镜中的你·哭脸（胆小的自己）：瑟缩迟疑，总在示警；与主角：她会在你接近真相时尖叫\n- 背对着的你（遗失的恐惧）：沉默，始终背对；与主角：它一转身，迷宫就会坍缩\n\n【时间线】\n起始：2026年8月1日\n备注：你注射药剂的第三夜，第一次在迷宫里遇见白医生的尸体——他应该正在诊所值班\n\n【选项风格】选项要带梦境与现实交织的悬疑（如：追问镜中的你/检查尸体/尝试打破镜子/寻找醒来的方法）",
