    "text": "【世界设定】\n时代：现代·日常副本\n题材：无限流\n简介：超市的广播温柔地响起：「亲爱的顾客，营业时间即将结束，请抓紧时间选购。」你被困在一家 24 小时超市里，货架上的商品会「刷新」，收银台永远坐着同一个面无表情的店员。规则贴在购物车把手上：「1. 每件商品都有它的价值。2. 价值过高的商品，不要看。3. 结账时，收银员会找给你零钱。4. 零钱可以买时间。5. 时间用完了，你就是商品。」你是个刚下班的白领，只是想买瓶水，却被困在这家超市的「午夜场」里。\n规则：\n  1. 超市规则：商品会刷新，标价会变化，夜里的货架「活」着\n  2. 收银员的找零=时间，买不起就借，借了要还\n  3. 价值过高的商品会「标记」你，被标记三次会被「上架」\n  4. 超市的广播每小时响一次，报的都是「促销信息」\n  5. 出口在收银台后面，但每个出口都需要「一张小票」\n氛围：超市的日光灯惨白，货架整齐得过分，广播里的音乐轻快而循环，冷藏柜的灯在夜里发出幽蓝的光\n\n【主角身份】\n姓名：苏芃\n性别：女\n年龄：26\n背景：普通公司白领，加班到深夜想买瓶水，却被困在超市「午夜场」，穿着高跟鞋和西装裙，购物车是唯一的依靠\n\n【重要人物】\n- 收银员·无脸（收银台店员）：面无表情，动作机械；与主角：他的找零是时间，他的微笑是警告\n- 理货员·老周（货架理货员）：疲惫世故，话里有话；与主角：他推着货车上夜班，知道货架的「规矩」\n- 顾客·西装男（另一名被困者）：冷静精明，经验丰富；与主角：他已经被困了三晚，知道怎么「活下去」\n- 高价值商品·红盒子（货架顶层的神秘商品）：（商品）会发光；与主角：它的标价是一串零，它盯上你了\n\n【时间线】\n起始：2026年12月24日\n备注：平安夜的凌晨 00:00，广播宣布「午夜场开始」，你刚刚注意到购物车把手上贴着的五条规则\n\n【选项风格】选项要带日常场景的荒诞感（如：先买水结账/找老周问规矩/跟着西装男/看红盒子）",
