    "text": "【世界设定】\n时代：现代·高中\n题材：校园\n简介：期中考试前一天，你脑袋里「叮」的一声，出现了一个自称「学霸系统」的东西。它能预测考题、过目不忘、模拟解题，甚至可以「跳过」你不想学的科目。代价是：每用一次，它都会悄悄抽走你一样东西——先是你的睡眠，然后是你的朋友，再然后是……你害怕了。当系统进度条涨到 99% 时，你终于明白：它不是帮你变强的工具，它是来「接管」你的。\n规则：\n  1. 系统功能：预测/记忆/模拟，使用需消耗「精力值」\n  2. 精力值用尽后，系统会自行「抽取」你的生活\n  3. 系统不会撒谎，但它从不说出全部规则\n  4. 考试成绩突然暴涨会引起注意，注意会导致调查\n  5. 卸载系统的唯一方法，系统拒绝回答\n氛围：教室里日光灯惨白，屏幕上的倒计时在跳动，你耳机里时不时传来一声冰冷的「叮」\n\n【主角身份】\n姓名：程宇\n性别：男\n年龄：17\n背景：普通高中生，成绩中游，父母离异，住校生。为了考上理想的大学，第一次在系统提示下使用了「考题预测」\n\n【重要人物】\n- 系统·学神（「学霸系统」）：冰冷高效，语调无波；与主角：它帮你，也在慢慢拿走你的东西\n- 同桌·阿豪（你的同桌）：懒散仗义，成绩垫底；与主角：你最好的朋友，最近总觉得你不对劲\n- 班主任·王姐（高三班主任）：敏锐尽责，关心学生；与主角：她注意到你成绩的异常暴涨\n- 神秘转学生·零（突然转来的学生）：安静冷淡，仿佛在观察你；与主角：他看你的眼神，像在看一个「同类」\n\n【时间线】\n起始：2026年11月8日\n备注：期中考试前一天深夜，系统弹出提示：「明日考题预测服务，是否开启？」，进度条停在 17%\n\n【选项风格】选项要带与系统博弈的紧张感（如：继续使用/询问规则/试探转学生/拒绝系统）",
