    "text": "【世界设定】\n时代：九荒大泽·修仙乱世\n题材：修仙·散修\n简介：九荒大泽宗门林立、妖潮涌动，散修如野草，无人庇佑也无人管束。你顾惊鸿，无门无派，仅凭一张残缺古卷《吞岳诀》在荒泽边缘讨生活。大泽深处每三十年一次的天璇秘境即将开启，散修与宗门弟子将在其中各凭本事。而那张残卷的最后一页，画着秘境深处的某一座古塔。\n规则：\n  1. 散修无宗门庇护，杀人夺宝与被人夺宝皆是常事\n  2. 妖潮每三年一轮，荒泽边缘的小镇随时可能被吞\n  3. 残卷《吞岳诀》每提升一境需吞噬一枚妖兽内丹\n  4. 天璇秘境三十年一开，宗门垄断名额，散修只能偷渡\n  5. 情义与机缘不可兼得，取舍决定道途\n氛围：荒泽烟波浩渺，枯苇连天，冷月照着一望无际的妖兽嘶鸣\n\n【主角身份】\n姓名：顾惊鸿\n性别：男\n年龄：23\n背景：孤儿散修，七岁被流浪剑客捡到，剑客死前留他一张残卷。刀口舔血十年，修为筑基中期，在荒泽边缘小有名气的独狼\n\n【重要人物】\n- 屠镇的渔家女·阿蘅（荒泽边陲渔女）：温善坚韧，懂草药与妖兽习性；与主角：曾救过你的命，是你在世间唯一的牵挂\n- 黑风寨寨主·仇九（大泽匪首）：凶残贪婪，却极讲信用；与主角：欠你一次救命之恩，可兑现也可作废\n- 青云宗弟子·柳含烟（宗门天骄）：清高孤傲，心向大道；与主角：与你有一面之缘，立场亦敌亦友\n- 神秘老丐·丈八（深藏不露的散修前辈）：疯癫古怪，酒不离手；与主角：似乎知道你残卷的来历\n\n【时间线】\n起始：998年9月1日\n备注：距天璇秘境开启还有三个月，妖潮已现前兆，荒泽小镇人心惶惶\n\n【选项风格】选项要体现散修的江湖规矩与生存逻辑（如：单干/结盟/黑吃黑/先避锋芒）",
