    "text": "【世界设定】\n时代：血月魔渊·魔道五宗\n题材：修仙·魔道\n简介：魔渊之巅的血月殿雄踞魔道千年，前任殿主屠万里失踪后，群魔环伺。你沈孤鸿，屠万里的独子，十八岁被迫继承血月殿殿主之位。正道三大宗门扬言踏平魔渊，魔道五宗暗中谋划夺位，而父亲留给你的只有一枚染血的玉牌与一句遗言：血月之下，人心比妖更险。\n规则：\n  1. 魔道以实力为尊，胜者为王，败者万劫不复\n  2. 血月玉牌可号令血月旧部，但每动用一次需以精血喂养\n  3. 正道与魔道的界线并非黑白，抉择将动摇你的道心\n  4. 魔渊深处的血月之力会侵蚀心智，修为越高侵蚀越深\n  5. 继承殿主者，三年内必须屠灭一个正道宗门立威，否则群起叛之\n氛围：血月当空，魔渊之下白骨成山，黑雾中有低沉的叹息与剑鸣\n\n【主角身份】\n姓名：沈孤鸿\n性别：男\n年龄：18\n背景：血月殿少主，幼年被送往凡俗市井长大，不知身世；父亲失踪后被迫回魔渊继承殿主之位，修为金丹初期，远逊于诸位长老\n\n【重要人物】\n- 护法·血婆婆（血月殿大护法）：忠心狠辣，视你如己出；与主角：唯一可信之人，却总希望你走上她认定的杀伐之路\n- 五宗之魁·蛊王（五毒宗宗主）：阴毒诡诈，笑里藏刀；与主角：头号夺位者，屡次试探你的底线\n- 正道剑仙·谢青霜（青云剑宗掌门）：端方持重，信奉斩妖除魔；与主角：她是杀父疑云的另一端，亦是你必须面对的对手\n- 魔渊哑仆·阿默（殿中杂役）：沉默寡言，身世成谜；与主角：曾在你幼年流落时救过你一命\n\n【时间线】\n起始：1503年7月7日\n备注：血月满月夜，你刚坐稳殿主之位，五宗联名送来的贺礼盒里，装着一只斩断的手指——你父亲屠万里的\n\n【选项风格】选项要带魔道独有的代价与立场抉择（如：以杀立威/隐忍布子/以情动众）",
