    "text": "【世界设定】\n时代：玄天宗·东荒\n题材：修仙·逆袭\n简介：玄天宗乃东荒第一仙门，弟子万千，可你陆小凡只是杂役处一个劈柴挑水的杂役，灵根微弱，被人踩在泥里。直到某日你劈柴时劈裂了一块平平无奇的柴墩——那里面藏着一座上古洞府。洞府的主人自称「守山老怪」，自称当年同玄天宗祖师八拜之交，被镇压于此三千年。他答应教你真正的仙法，条件是：替他找出当年背叛他、把他骗进柴墩的仇人。\n规则：\n  1. 杂役身份是最大的枷锁，也是最好的掩护\n  2. 守山老怪所言真假参半，他的话要反复推敲\n  3. 玄天宗内派系林立，站错队可能粉身碎骨\n  4. 灵根微弱并非绝路，上古洞府中有改命之法\n  5. 机缘往往以最不起眼的形式出现\n氛围：宗门巍峨如天上宫阙，杂役院却矮墙漏雨，纸灯笼在风里晃\n\n【主角身份】\n姓名：陆小凡\n性别：男\n年龄：15\n背景：玄天宗杂役处杂役，六岁被卖进宗门，灵根微弱（木属性下品），干活麻利，人缘尚可\n\n【重要人物】\n- 守山老怪·无名（洞府残魂）：玩世不恭，亦正亦邪，话里藏话；与主角：你的便宜师父，也是你最大的变数\n- 杂役头·刘四（杂役处管事）：欺软怕硬，克扣工钱；与主角：日常压迫你，暗地里却怕你知道他的把柄\n- 内门天骄·楚凌霄（玄天宗首席弟子）：骄傲磊落，剑道无双；与主角：一次善缘结下的亦敌亦友\n- 藏经阁老妪·文婆婆（藏经阁守阁人）：慈眉善目，来头惊人；与主角：允许你偷偷抄录残卷，似乎认得洞府的存在\n\n【时间线】\n起始：2093年4月1日\n备注：宗门十年一度的收徒大典在即，杂役们蠢蠢欲动，而你刚发现柴墩的秘密\n\n【选项风格】选项要带底层视角的机智与谨慎（如：藏拙扮傻/暗中修炼/借势上位）",
