    "text": "【世界设定】\n时代：1930年代·临海旧港\n题材：悬疑\n简介：1937年的临海港，大雾常年不散。港口的报关行、码头仓库、巡捕房、舞厅之间，暗流涌动。你是新上任的巡捕房探长，刚接手一桩悬案：港口最大的货商沈家老爷死在自己的书房里，死因成谜，遗书却在尸体被发现前就登上了报纸。市长施压，商会施压，码头工人罢工，而你手头唯一的线索是一枚被死者攥在手里的船票——开往大洋彼岸，日期是后天的。\n规则：\n  1. 1937年临海港：租界、帮派、走私、情报网交织\n  2. 证据链：指纹、字迹、船票、尸检报告都可能有假\n  3. 巡捕房的权力有限，有些案子只能点到为止\n  4. 每个人都有一张船票，是逃离也是等待\n  5. 大雾里的港口，看不见的比看得见的多\n氛围：港口的雾终年不散，汽笛声从雾里传来，像谁在咳嗽\n\n【主角身份】\n姓名：沈砚秋\n性别：男\n年龄：33\n背景：新上任的巡捕房探长，之前在北平办过三桩大案，调来临海港，与沈家无亲，但上任第一天就被告知：沈家老爷的死，和你的前任探长的失踪有关\n\n【重要人物】\n- 副探长·老猫（巡捕房副探长）：油滑老练，人脉极广；与主角：熟知港口一切黑幕，亦正亦邪\n- 沈夫人·白露（沈家遗孀）：美艳冷静，滴水不漏；与主角：死者的续弦妻子，嫌疑最大也最无辜\n- 舞女·红菱（百乐门舞女）：伶俐世故，记性极好；与主角：声称掌握关键线索，但要价不低\n- 码头老大·陈三（码头帮派头目）：豪爽凶悍，重江湖义气；与主角：与沈家有旧怨，也是港口消息的源头\n\n【时间线】\n起始：1937年6月9日\n备注：沈家老爷死后第七天，你正式接手此案，尸检报告和遗书正在你桌上\n\n【选项风格】选项要带刑侦逻辑与时代感（如：验尸/查船票/试探证人/追踪走私线）",
