    "text": "【世界设定】\n时代：民国·深宅大院\n题材：悬疑\n简介：你从父辈的遗物里继承了一座民国老宅——落霞府。八进八出的宅子，前七进已经被翻新成民宿，唯独第八进被锁了三十年。钥匙在你手里，也带来了一个传说：民国年间，落霞府的主人一夜之间全家失踪，只留下一个烧焦的房间。你打开第八进的那天，发现房间的布置和你儿时梦里的场景一模一样——而墙上挂着一幅你从没见过的全家福，照片里站在角落里的人，和你长着一模一样的脸。\n规则：\n  1. 老宅的八个房间，只有第八个会在午夜「活过来」\n  2. 照片里的人会移动位置，但从来没人看见它动\n  3. 老宅的地板下有暗道，只有第八进有入口\n  4. 与宅子有关的旧报纸和族谱，都被烧过一部分\n  5. 每个进来的人都会忘记一些事，只有你能记住\n氛围：老宅的雕花门廊上积着灰，夜风穿过回廊时发出呜咽，像是谁在哼一支旧歌\n\n【主角身份】\n姓名：顾明远\n性别：男\n年龄：27\n背景：历史系研究生，继承落霞府后辞掉工作搬进老宅，白天整理古籍，晚上和宅子打交道，天生能记住细节\n\n【重要人物】\n- 管家·福伯（老宅老管家）：沉默守旧，忠于顾家；与主角：从小看护这宅子，知道第八进的秘密\n- 民宿住客·白女士（长期住客）：优雅神秘，身份成谜；与主角：住了半年，似乎专门为第八进而来\n- 旧货商·钱掌柜（收购旧物的商人）：精明贪婪，消息灵通；与主角：手上有一批落霞府流出的旧物\n- 族谱整理人·阿禾（档案馆实习生）：细心执着，一丝不苟；与主角：帮你查族谱，查出一个惊人的名字\n\n【时间线】\n起始：2026年11月15日\n备注：你搬进落霞府第四十天，终于用钥匙打开了第八进的门\n\n【选项风格】选项要带解谜与氛围感（如：对照全家福/查暗道/问福伯/翻旧物）",
