    "text": "【世界设定】\n时代：2020年代·影视寒冬\n题材：娱乐圈\n简介：影视寒冬，大厂裁员，小公司倒闭。你陈砚秋，四十五岁，演了一辈子黄金配角的实力派，戏红人不红，奖拿了一堆，片酬不如流量新人的零头。攒了一辈子钱，在影视城边上盘下一间破工作室，带着三个不成器的徒弟，专接别人不要的硬骨头角色。有人劝你放下身段去带货，有人说你过气，但你知道——真正的戏，还没演完。\n规则：\n  1. 影视寒冬：横店群演日薪跌破百元，剧组不断跑路\n  2. 老戏骨的尊严：不炒CP、不卖惨、不拍烂戏\n  3. 带新人就是带自己，徒弟的戏路决定工作室的存亡\n  4. 资本与资历的博弈：流量片酬千万，你只能谈剧本\n  5. 有些角色一旦接了，就再也洗不白\n氛围：影视城的青砖墙皮斑驳，工作室的茶水永远泡着便宜的茶叶\n\n【主角身份】\n姓名：陈砚秋\n性别：男\n年龄：45\n背景：国家一级演员，演过四十多部剧的黄金配角，三个徒弟：一个灵气、一个憨直、一个学艺不精却最像当年的自己\n\n【重要人物】\n- 徒弟·小白（工作室大徒弟）：灵气逼人，戏痴；与主角：你的希望，也是你最大的软肋\n- 导演·何苦（拍烂片起家的导演）：圆滑市侩，深谙流量密码；与主角：总想把你的徒弟拉去拍烂片\n- 制片人·柳艳（大制片厂制片人）：强势精算，只看市场；与主角：手握好项目，却想换掉你的徒弟\n- 徒弟·阿福（工作室三徒弟）：怯懦自卑，笨拙努力；与主角：最像年轻时的你，最不被看好\n\n【时间线】\n起始：2024年11月8日\n备注：工作室欠租三个月，柳艳带着一个好项目找上门——条件是徒弟小白必须让位给流量新人\n\n【选项风格】选项要带中年人的进退取舍（如：卖房保工作室/让徒弟让位/接烂片养家/破釜沉舟）",
