    "text": "【世界设定】\n时代：架空·青石县\n题材：种田\n简介：一觉醒来，你成了青石县李家庄的李小满——爹娘双亡，家中只剩三亩薄田、一间漏雨的茅屋、一个嗷嗷待哺的弟弟。青石县山清水秀，民风淳朴，但苛捐杂税年年涨，地主赵员外霸着好田，县里的粮商压价收粮。你带着现代人的头脑，在这个小村庄里开始了种田养家的日子：育种、沤肥、养鸡、开荒，一点一点，把日子过出花来。\n规则：\n  1. 农时不可违：春种秋收，误一季就是饿一年\n  2. 税赋沉重：夏税秋粮，青黄不接时最难熬\n  3. 地主与粮商联手压价，小农户没有议价权\n  4. 村里人情往来是生存法则，红白喜事都要到场\n  5. 种地之外，手艺、副业、读书是翻身的三种路\n氛围：晨雾里的青石县，鸡鸣犬吠，田埂上的露水打湿布鞋，灶膛里的柴火噼啪作响\n\n【主角身份】\n姓名：李小满\n性别：女\n年龄：16\n背景：穿越者，原主父母双亡，家中三亩薄田，弟弟李小米八岁，还有一个瘫痪在床的奶奶，日子穷得揭不开锅\n\n【重要人物】\n- 弟弟·李小米（弟弟）：机灵懂事，黏人；与主角：你在这个世界唯一的亲人\n- 奶奶·李氏（祖母）：慈祥硬朗，深谙农事；与主角：她年轻时是十里八乡有名的种地好手\n- 地主·赵员外（青石县地主）：贪婪精明，笑里藏刀；与主角：他盯着你家那三亩地好久了\n- 邻家·陈二婶（隔壁邻居）：热心泼辣，消息灵通；与主角：村里的八卦中心，也是你的人情枢纽\n\n【时间线】\n起始：1036年3月1日\n备注：春耕将至，你家的种子被老鼠祸害了一半，赵员外派人来「问」地，弟弟饿得直哭\n\n【选项风格】选项要带种田的踏实与生计（如：换良种/赊粮过春/开荒种豆/做小买卖）",
