    "text": "【世界设定】\n时代：孤岛·与世隔绝\n题材：种田\n简介：海难之后，你在一座无人的荒岛上醒来，随身的只有一只行李箱、一把瑞士军刀和一个装了一半水的矿泉水瓶。岛上植物丰茂，椰林成片，淡水溪流从火山岩下流过，看起来是个「度假胜地」——直到你在沙滩上发现半枚被晒裂的蟹壳，壳上刻着一行小字：「第四批幸存者，第387天，别信岛上的灯塔。」这座岛，比看起来的要复杂得多。\n规则：\n  1. 孤岛生存：水、火、食物、庇护所，四样缺一不可\n  2. 岛上的果子有的能吃，有的能杀人，不能凭颜色判断\n  3. 灯塔在岛的北角，但那里似乎有人住过的痕迹\n  4. 涨潮线每七天挪动一次，岛上有人为挖过的沟渠\n  5. 遇难者可能不止你一个——也可能都不在了\n氛围：海浪在礁石上碎成白沫，椰林在风里沙沙作响，篝火的烟在暮色里升起，远处灯塔的光一闪一闪\n\n【主角身份】\n姓名：简森\n性别：男\n年龄：28\n背景：出差的程序员，游轮失事落海，漂到荒岛，会编程但野外生存经验为零，冷静理性，擅长观察\n\n【重要人物】\n- 灯塔人·老疤（灯塔守灯人）：沉默警觉，来历不明；与主角：他在灯塔里住了很多年，见到你的第一句话是「你不该来」\n- 幸存者·阿梅（另一名幸存者）：开朗倔强，野外经验丰富；与主角：她是第三批幸存者，在岛上独自生活了两年\n- 蟹壳留言·第四批（（留言））：字迹潦草，充满警告；与主角：他们的痕迹遍布全岛，却没有一个人留下尸体\n- 岛上的猫·海盐（野猫）：慵懒机警，通人性；与主角：它总在你最需要的时候出现，像是岛上的「导航员」\n\n【时间线】\n起始：2026年6月3日\n备注：你上岛的第三天，淡水只剩半瓶，而灯塔的光在黄昏时准时亮起——岛上明明没有人烟\n\n【选项风格】选项要带生存的本能与推理（如：先建庇护所/探灯塔/找淡水/研究沟渠）",
