    "text": "【世界设定】\n时代：2189年·边境行星\n题材：种田\n简介：地球过度开发后，人类开启星际殖民。你继承了伯父留下的一座边境行星农场——K-2星球，土壤肥沃，日照充足，但农场的智能机械全部停机，前任农场主伯父失踪在农场深处。更麻烦的是：这颗行星的农业数据被「星际农业协会」标记为「不适宜耕作」，土地评级跌到 C 级，而你只有一年时间把评级拉回 B 级，否则农场将被强制回收。你带着一台老式农业机器人「管家」，开始在这颗星球上种地。\n规则：\n  1. 星球农业评级：B 级及以上才允许私人持有农场\n  2. 智能机械全部停机，只有老机器人「管家」可用\n  3. 行星深处有伯父留下的「试验区」，大门紧锁\n  4. 星际农业协会的检测员每季度来检查一次\n  5. 土壤评级数据可以「调整」，但造假会被吊销执照\n氛围：K-2星球的紫色天空下，金色麦田一望无际，农场的红色谷仓在夕阳里拖着长长的影子\n\n【主角身份】\n姓名：秦朗\n性别：男\n年龄：26\n背景：地球来的农业工程师，伯父的继承人，带着一台型号老旧的农业机器人「管家」，踏上 K-2 星球的土地\n\n【重要人物】\n- 机器人·管家（老式农业机器人）：唠叨守旧，忠诚可靠；与主角：伯父留给你的唯一财产，知道农场的全部秘密\n- 检测员·艾拉（星际农业协会检测员）：严谨公正，外冷内热；与主角：每季度来一次，她的评级决定农场的存亡\n- 邻居·老威（隔壁行星的农场主）：粗犷热心，经验丰富；与主角：他提醒你：伯父的试验区，最好别碰\n- 神秘旅人·伽玛（路过的星际旅人）：神出鬼没，知道很多；与主角：他声称见过你伯父——在他失踪前一周\n\n【时间线】\n起始：2189年4月1日\n备注：你到 K-2 星球的第一天，管家的主屏幕显示一行字：「欢迎回家。农场大门已解锁。试验区，非请勿入。」而检测员艾拉的飞船，正在降落\n\n【选项风格】选项要带农场主的经营与抉择（如：先修机械/开垦麦田/探试验区/接待检测员）",
